from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (available_date, points_remaining)
        self._points = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")
        points = int(amount // 10)
        available_on = day + timedelta(days=14)
        self._points.setdefault(customer, []).append([available_on, points])
        return points

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        total = 0
        for available_on, remaining in self._points.get(customer, []):
            if available_on <= day:
                total += remaining
        return total

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points < 0:
            raise ValueError("Cannot redeem a negative number of points")
        available = self.balance(customer, day)
        if points > available:
            raise ValueError("Insufficient points available")
        if points == 0:
            return
        # Spend from the oldest available points first (FIFO)
        entries = self._points.get(customer, [])
        available_entries = sorted(
            (e for e in entries if e[0] <= day and e[1] > 0),
            key=lambda e: e[0],
        )
        to_redeem = points
        for entry in available_entries:
            if to_redeem <= 0:
                break
            used = min(entry[1], to_redeem)
            entry[1] -= used
            to_redeem -= used
